param([string]$BenchmarkRepo="D:\Dev\LotSizingDataModel.Benchmarks")
Set-StrictMode -Version Latest;$ErrorActionPreference="Stop";$g=Join-Path $BenchmarkRepo "catalog\global";$t=@(Import-Csv (Join-Path $g "GLOBAL-NORMALIZED-TRUST-v0.20.0.csv"));$x=@(Import-Csv (Join-Path $g "GLOBAL-TRUST-TRANSITIONS-v0.20.0.csv"));$q=@(Import-Csv (Join-Path $g "GLOBAL-RESULT-QUARANTINE-v0.20.0.csv"))
if($t.Count-ne7888-or@($t.global_instance_id|Sort-Object -Unique).Count-ne7888){throw "Registry invariant failed."};if($x.Count-ne96-or@($t|Where-Object{$_.family-eq"DJ2000"-and$_.normalized_trust_status-eq"CHECKER_VERIFIED_FEASIBLE"}).Count-ne96){throw "DJ feasibility promotion guard failed."};if(@($t|Where-Object{$_.family-eq"DJ2000"-and$_.normalized_trust_status-eq"VERIFIED_PROVEN_OPTIMAL"}).Count-ne0){throw "Unsupported optimality promotion."};if($q.Count-lt1-or@($q|Where-Object { $_.promotion_allowed -ne "False" }).Count-ne0){throw "Quarantine guard failed."};Write-Host "ACCELERATION_V0.20.0_VALID";Write-Host "ROWS|7888";Write-Host "DJ_CHECKER_VERIFIED_FEASIBLE|96";Write-Host "DJ_VERIFIED_PROVEN_OPTIMAL|0";Write-Host("QUARANTINE|"+$q.Count)
